def gen(rng):
    def build(n, q, pc, D, wm, wr, wc, deep_mk=False):
        # initial tree
        par = {1: 0}
        depth = {1: 1}
        order = [1]
        for v in range(2, n + 1):
            while True:
                if rng.random() < pc and depth[v - 1] < D:
                    p = v - 1
                else:
                    p = rng.randint(1, v - 1)
                if depth[p] < D:
                    break
            par[v] = p
            depth[v] = depth[p] + 1
        labels = list(range(2, n + 1))
        rng.shuffle(labels)
        lab = {1: 1}
        for i, v in enumerate(range(2, n + 1)):
            lab[v] = labels[i]
        edges = []
        for v in range(2, n + 1):
            a, b = lab[par[v]], lab[v]
            edges.append((a, b) if rng.random() < 0.5 else (b, a))
        rng.shuffle(edges)
        # simulation in label space
        parent = {1: 0}
        dep = {1: 1}
        children = {l: set() for l in range(1, n + 1)}
        for v in range(2, n + 1):
            parent[lab[v]] = lab[par[v]]
            dep[lab[v]] = depth[v]
            children[lab[par[v]]].add(lab[v])
        pool = list(range(1, n + 1))
        where = {x: i for i, x in enumerate(pool)}

        def pool_remove(x):
            i = where.pop(x)
            last = pool.pop()
            if last != x:
                pool[i] = last
                where[last] = i

        fresh = list(range(n + 1, n + q + 1))
        rng.shuffle(fresh)
        recent = []
        ops = []
        ncount = 0
        for step in range(q):
            r = rng.random() * (wm + wr + wc)
            if step == q - 1 and ncount == 0:
                r = wm + wr + 0.0001 if wc > 0 else r
            if r < wm:
                x = None
                for _ in range(10):
                    if deep_mk and recent and rng.random() < 0.7:
                        c = rng.choice(recent[-30:])
                        if c not in where:
                            continue
                    else:
                        c = rng.choice(pool)
                    if dep[c] < D:
                        x = c
                        break
                if x is not None:
                    y = fresh.pop()
                    children[x].add(y)
                    children[y] = set()
                    parent[y] = x
                    dep[y] = dep[x] + 1
                    where[y] = len(pool)
                    pool.append(y)
                    recent.append(y)
                    ops.append(f'mkdir {x} {y}')
                    continue
                r = wm + wr + 0.0001
            if r < wm + wr and len(pool) > 1:
                x = rng.choice(pool)
                if x == 1:
                    x = rng.choice(pool)
                if x != 1:
                    children[parent[x]].discard(x)
                    st = [x]
                    while st:
                        u = st.pop()
                        st.extend(children[u])
                        del children[u]
                        pool_remove(u)
                    ops.append(f'rmdir {x}')
                    continue
            x = rng.choice(pool)
            ops.append(f'count_subdir {x}')
            ncount += 1
        head = f'{n} {len(ops)}\n'
        return head + '\n'.join(f'{a} {b}' for a, b in edges) + ('\n' if edges else '') + '\n'.join(ops)

    tests = [
        '1 2\nmkdir 1 2\ncount_subdir 1',
        '2 3\n2 1\ncount_subdir 1\nrmdir 2\ncount_subdir 1',
        '4 6\n3 4\n1 4\n2 1\ncount_subdir 1\ncount_subdir 4\nrmdir 4\ncount_subdir 1\nmkdir 2 5\ncount_subdir 2',
        '5 7\n1 2\n3 2\n4 3\n5 4\ncount_subdir 2\nrmdir 3\ncount_subdir 2\nmkdir 2 6\nmkdir 6 7\ncount_subdir 2\ncount_subdir 1',
    ]
    for _ in range(14):
        n = rng.randint(1, 10)
        q = rng.randint(3, 14)
        tests.append(build(n, q, rng.choice([0.0, 0.5, 0.9]), 50, 3, 2, 4))
    for _ in range(6):
        tests.append(build(rng.randint(10, 25), rng.randint(15, 30), rng.choice([0.2, 0.7]), 50, 4, 2, 4, deep_mk=True))
    n = 20000
    q = 20000
    tests.append(build(n, q, 0.0, 5000, 5, 1, 5))
    tests.append(build(n, q, 0.9, 5000, 5, 1, 5, deep_mk=True))
    tests.append(build(n, q, 0.995, 5000, 6, 1, 4, deep_mk=True))
    tests.append(build(n, q, 0.5, 5000, 4, 3, 4))
    return tests
